SELECT proposals.* FROM (VALUES
  ('nexora-concept-neon-harbor', 'neon-harbor', 'MOVIE', 'Neon Harbor', 'ميناء النيون', 'An original film concept proposed for Nexora. A courier in a futuristic Casablanca discovers that a mysterious package carries the key to a citywide secret. Coming soon; no release date has been announced.', 'فكرة فيلم أصلية مقترحة لنكسورا. تكتشف سائقة توصيل في دار بيضاء مستقبلية أن طردًا غامضًا يحمل مفتاح سر يهدد المدينة. قريبًا؛ لم يُحدد موعد عرض.', 'Sci-Fi, Thriller', 'خيال علمي، تشويق', '/media/movies/neon-harbor.webp', 'Coming soon · Proposed film', 'قريبًا · فيلم مقترح', true, true, false, false),
  ('nexora-concept-atlas-at-dawn', 'atlas-at-dawn', 'MOVIE', 'Atlas at Dawn', 'فجر الأطلس', 'An original film concept proposed for Nexora. Two estranged siblings follow a forgotten mountain trail toward a remote refuge, confronting their past as dawn breaks over the Atlas. Coming soon; no release date has been announced.', 'فكرة فيلم أصلية مقترحة لنكسورا. يتبع شقيقان فرّقتهما السنوات دربًا جبليًا منسيًا نحو ملجأ بعيد، ويواجهان ماضيهما مع بزوغ الفجر فوق الأطلس. قريبًا؛ لم يُحدد موعد عرض.', 'Adventure, Drama', 'مغامرة، دراما', '/media/movies/atlas-at-dawn.webp', 'Coming soon · Proposed film', 'قريبًا · فيلم مقترح', true, true, false, false),
  ('nexora-concept-the-last-lantern', 'the-last-lantern', 'MOVIE', 'The Last Lantern', 'الفانوس الأخير', 'An original film concept proposed for Nexora. An artisan in the old city of Fez inherits a lantern whose light reveals paths that disappear before sunrise. Coming soon; no release date has been announced.', 'فكرة فيلم أصلية مقترحة لنكسورا. يرث حرفي في مدينة فاس العتيقة فانوسًا يكشف ضوؤه طرقًا تختفي قبل شروق الشمس. قريبًا؛ لم يُحدد موعد عرض.', 'Fantasy, Mystery', 'فانتازيا، غموض', '/media/movies/the-last-lantern.webp', 'Coming soon · Proposed film', 'قريبًا · فيلم مقترح', true, true, false, false),
  ('nexora-concept-letters-to-the-sea', 'letters-to-the-sea', 'MOVIE', 'Letters to the Sea', 'رسائل إلى البحر', 'An original film concept proposed for Nexora. In Essaouira, an artist finds a collection of unsent letters and follows their story toward an unexpected second chance. Coming soon; no release date has been announced.', 'فكرة فيلم أصلية مقترحة لنكسورا. تعثر فنانة في الصويرة على رسائل لم تُرسل، وتتبع حكايتها نحو فرصة ثانية غير متوقعة. قريبًا؛ لم يُحدد موعد عرض.', 'Romance, Drama', 'رومانسي، دراما', '/media/movies/letters-to-the-sea.webp', 'Coming soon · Proposed film', 'قريبًا · فيلم مقترح', true, true, false, false),
  ('nexora-concept-midnight-delivery', 'midnight-delivery', 'MOVIE', 'Midnight Delivery', 'توصيل منتصف الليل', 'An original film concept proposed for Nexora. One oversized package turns a bicycle courier''s final delivery into a chaotic night through Marrakesh''s markets and hidden alleys. Coming soon; no release date has been announced.', 'فكرة فيلم أصلية مقترحة لنكسورا. يحوّل طرد ضخم آخر طلب توصيل لسائق دراجة إلى ليلة مليئة بالمواقف الطريفة في أسواق مراكش وأزقتها الخفية. قريبًا؛ لم يُحدد موعد عرض.', 'Comedy, Adventure', 'كوميديا، مغامرة', '/media/movies/midnight-delivery.webp', 'Coming soon · Proposed film', 'قريبًا · فيلم مقترح', true, true, false, false),
  ('nexora-concept-the-glass-observatory', 'the-glass-observatory', 'MOVIE', 'The Glass Observatory', 'المرصد الزجاجي', 'An original film concept proposed for Nexora. A young astronomer at a remote desert observatory sees a sky that no longer matches the universe she knows. Coming soon; no release date has been announced.', 'فكرة فيلم أصلية مقترحة لنكسورا. تكتشف عالمة فلك شابة في مرصد صحراوي بعيد سماءً لم تعد تشبه الكون الذي تعرفه. قريبًا؛ لم يُحدد موعد عرض.', 'Sci-Fi, Adventure', 'خيال علمي، مغامرة', '/media/movies/the-glass-observatory.webp', 'Coming soon · Proposed film', 'قريبًا · فيلم مقترح', true, true, false, false)
) AS proposals("id", "slug", "type", "name", "nameAr", "description", "descriptionAr", "genres", "genresAr", "posterUrl", "releaseLabel", "releaseLabelAr", "comingSoon", "published", "isFree", "featured")
WHERE NOT EXISTS (SELECT 1 FROM "Setting" WHERE "key" = 'catalog:20261026:movie-concepts')
